"""Component p-82af68dd@100000/layers.15.mlp.down_proj:4810 (layer 15 MLP down-projection).

What it is, plainly: a weak, diffuse direction in the MLP's hidden layer. Its activation
is a small, mostly-random-looking number at almost every token (std about 0.34, almost
always within +/-1), and no token identity, token class or neighbouring word explains
it: a lookup table on the current token, or on the previous token, explains nothing
out of sample, and a linear model on a 16-token window explains about 2%. It is
essentially never important to the model's output (switching it off changes next-token
loss by about 2e-5 nats).

So this program only captures the few regularities that are real and simple:
  * the first token of every document is silent (activation about 0);
  * the second token of a document is pushed slightly negative;
  * chat / tool-call markup tokens (<|im_end|>, <think>, <tool_call>, ...) are pushed
    positive, by about 0.3;
  * punctuation-only tokens (brackets, operators, quotes, '.', ',') sit about 0.05 higher;
  * everywhere else the value is a slow ramp from about -0.02 near the start of a
    document up to about +0.05 deep into it.
The ramp and the constants are averages over the training rows we measured.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

# Chat-template and tool-call markup tokens, as the tokenizer writes them.
MARKUP = {
    "<|im_end|>",
    "<think>",
    "</think>",
    "<tool_call>",
    "</tool_call>",
    "<tool_response>",
    "</tool_response>",
}


def is_punctuation(text):
    """True for a token made only of punctuation or symbols (an optional leading space allowed)."""
    body = text.strip()
    return body != "" and all(not (c.isalnum() or c.isspace()) for c in body)


def step(carry, prefix, upstream: Mapping):
    # carry: (document id of the previous token, its index within that document)
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        index = 0  # first token of a new document
    else:
        index = carry[1] + 1

    if index == 0:
        value = 0.0
    elif index == 1:
        value = -0.15
    elif prefix.token_strings[-1] in MARKUP:
        value = 0.3
    else:
        value = -0.02 + 0.07 * min(index, 300) / 300  # slow ramp into the document
        if is_punctuation(prefix.token_strings[-1]):
            value += 0.05
    return (doc, index), value

"""L15 MLP down_proj component 4812: a negative "of"-detector.

The component goes strongly negative on the word "of" when "of" attaches a
noun phrase to a head noun ("the ratio of", "the surface of", "each of"). It
is weaker when "of" is part of a fixed phrase ("because of", "instead of",
"out of", "aware of") or follows a classifier noun ("kind of", "part of",
"a lot of"). The same job is done, more weakly, by the "of" word of other
languages: de, di, van, von, der, des, del (European), của (Vietnamese),
的 and の (Chinese and Japanese possessive particles). A few prepositions
(to, with, on, at, for, from, by, about, or) sit slightly positive, and the
opening bracket and sentence-initial "The" slightly negative. Everything else
is about 0.
"""

READS = ()

# Words after which English "of" is usually a fixed phrase or discourse marker.
IDIOM_BEFORE_OF = {
    "because", "instead", "out", "think", "thinking", "terms", "instance",
    "aware", "capable", "full", "plenty", "regardless", "ahead", "rid",
    "composed", "consisting", "made",
}
# Classifier and quantity nouns that often take a light "of" ("a kind of", "a lot of").
CLASSIFIER_BEFORE_OF = {
    "kind", "form", "part", "lot", "number", "member", "way", "sense", "case",
    "use", "type", "variety", "amount", "one", "place", "front", "side", "set",
    "group", "presence",
}
# "of" in other languages, and the Chinese/Japanese possessive particles.
FOREIGN_OF = {" de", " di", " van", " von", " der", " des", " del", " của"}
POSSESSIVE_PARTICLE = {"的", "の"}
PREPOSITIONS = {" to", " with", " on", " at", " for", " from", " by", " about", " or"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok in FOREIGN_OF:
        return carry, -1.3
    if tok in POSSESSIVE_PARTICLE:
        return carry, -0.7
    if tok == "of":
        return carry, -1.4
    if tok in PREPOSITIONS:
        return carry, 0.3
    if tok in (" (", " The", "\n\n"):
        return carry, -0.5
    if tok not in (" of", " Of", " OF"):
        return carry, 0.0
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    word = prefix.token_strings[-2].strip().lower()
    if word in IDIOM_BEFORE_OF:
        return carry, -0.8
    if word in CLASSIFIER_BEFORE_OF:
        return carry, -2.3
    return carry, -3.6

"""Surface-class predictor for layers.15.mlp.down_proj:4832.

The component is almost silent in the model (causal importance about 1e-7; switching it
off changes next-token predictions by ~1e-6 nats). Its activation is noise-like, with
standard deviation 0.26, and almost none of it follows from the newest token's surface
form. The small class means below are the only consistent trend found: a bare word
piece leans slightly positive, a word after a space leans slightly negative, and line
breaks and spaces lean more negative. They explain well under 1% of the variance.
"""

READS = ()

CLASS_MEAN = {
    "word": 0.014,        # letters with no leading space, e.g. the "ers" in "copolymers"
    "spaced_word": -0.013,  # a word after a space
    "digit": -0.012,
    "punct": -0.006,
    "spaced_punct": -0.002,
    "space": -0.029,
    "newline": -0.045,
    "partial": -0.017,    # half of a multi-byte character
}


def token_class(s):
    if "�" in s:
        return "partial"
    body = s.strip()
    if body == "":
        return "newline" if "\n" in s else "space"
    lead = s[0] == " "
    if body.isdigit():
        k = "digit"
    elif body[0].isalpha():
        k = "word"
    else:
        k = "punct"
    if lead and k == "word":
        return "spaced_word"
    if lead and k == "punct":
        return "spaced_punct"
    return k


def step(carry, prefix, upstream):
    return carry, CLASS_MEAN.get(token_class(prefix.token_strings[-1]), -0.006)

"""Layer 15 MLP down_proj, component 4838.

Plain-terms summary. The component's activation is mostly near zero with rare large swings,
and its write direction (through the unembedding) suppresses comparison words such as
"like", "akin", "analogous" and 就像 / 如同. So the program predicts:

  * a clear negative value on a direct comparison word ("like", "unlike", "comme", "wie",
    как, 如, 就像, ...), the simile markers where the activation is most negative;
  * a weaker negative value on "as", "than", "similar";
  * a very small negative value on the few tokens just after such a word (same document);
  * a small positive value on a piece of a rare Latin-script word that is spread over several
    tokens (names and scientific words spelled out piecewise), where the activation leans positive;
  * 0 elsewhere.

It explains only a sliver of the variance: the large swings do not follow any token-level rule.
"""

from collections.abc import Mapping

import regex
import wordfreq

READS: tuple[str, ...] = ()

STRONG = {"like", "unlike", "comme", "wie", "как", "如", "就像", "如同", "不如", "犹如"}
WEAK = {"as", "than", "similar"}
PIECE = regex.compile(r"\p{Latin}+")
LANGS = ("en", "de", "fr", "es", "pt", "it")


def _rare(word: str) -> bool:
    return max(wordfreq.zipf_frequency(word.lower(), lang) for lang in LANGS) < 2


def step(carry, prefix, upstream: Mapping):
    toks = list(prefix.token_strings[-7:])
    docs = list(prefix.document_ids[-7:])
    cur = toks[-1]
    word = cur.strip().lower()
    if word in STRONG:
        return carry, -1.0
    if word in WEAK:
        return carry, -0.3
    if any(docs[j] == docs[-1] and toks[j].strip().lower() in STRONG | WEAK for j in range(len(toks) - 1)):
        return carry, -0.05
    # a rare word spelled out in several pieces: walk back over its pieces in this document
    pieces, j = [], len(toks) - 1
    while j >= 0 and docs[j] == docs[-1] and len(pieces) < 6 and PIECE.fullmatch(toks[j].strip() or "_"):
        pieces.insert(0, toks[j].strip())
        if toks[j][:1] == " ":
            break
        j -= 1
    if cur[:1] != " " and len(pieces) >= 2 and _rare("".join(pieces)):
        return carry, 0.1
    return carry, 0.0

"""Layer 15 MLP hidden unit 4847 (this component's contribution), read from the current token.

What it does: this component is one MLP hidden unit of layer 15, written out through its
down projection. Its output direction promotes words like "means", "refers", "meaning",
"clarify" and "unclear", so it lives in the model's "I am unsure what this is / what is meant"
mode. Its activation is positive on hesitation and clarification markers ("Wait", "Hmm",
"sorry", "Sure"), on question marks, and on the end of a user turn; it is negative on
conclusion connectives ("Therefore", "Thus", "So", "Since") and on chat role words
("assistant", "user").

This program predicts the activation from the current token alone, using the class means
measured on training text. It is a small lookup, not a full model of the component: most of its
variance is context-dependent and not captured by any token list.
"""

HESITATION = {"Wait", "wait", "Hmm", "Sure", "sorry", "Sorry"}
QUESTION_MARKS = {"?", "?\n\n", " ?\n\n", "?\n", " ?", "?)", "?),"}
TURN_END = {"<|im_end|>"}
CONCLUSION = {"Therefore", "Thus", "So", "Since", "These", "Alternatively", "Hence"}
ROLE_WORDS = {"assistant", "user"}

# class means measured on training text (mean activation per token in each class)
VALUES = {"hesitation": 1.7, "question": 0.4, "turn_end": 0.6, "conclusion": -0.4, "role": -0.4}

READS = ()


def _class_of(token):
    s = token.strip()
    if token in HESITATION or s in HESITATION:
        return "hesitation"
    if token in QUESTION_MARKS:
        return "question"
    if token in TURN_END:
        return "turn_end"
    if s in CONCLUSION:
        return "conclusion"
    if s in ROLE_WORDS:
        return "role"
    return None


def step(carry, prefix, upstream):
    # The activation depends only on the newest token, so the carry is unused.
    cls = _class_of(prefix.token_strings[-1])
    return carry, (VALUES[cls] if cls else 0.0)

"""Two patterns: name-joining hyphens and math-problem full stops.

1. The piece of a double-barrelled proper name just after its hyphen, when the
   hyphen joins two capitalised name parts: "Khan-[C]ullors", "Tallon-[B]audry",
   "Schmidt-[F]itzner". Strongest after a long surname; near zero for hyphens
   inside lower-case words or acronyms ("node-fetch", "SARS-CoV").
2. A full stop that ends an equation sentence in a maths problem, such as
   "Let f = -37 - -42[.] Calculate ...". Strong when the sentence just ended had
   an equals sign.
Clause-opening connectives ("And", "Und", "albeit") go negative. Everything else is 0.
"""

READS = ()

NAME_PART_MIN = 4  # letters in the title-case name part before the hyphen
MATH_CUES = ("Let ", "Calculate", "What is", "Solve", "Suppose", "Simplify", "Evaluate", "Factor")
CONNECTIVES = {" And": -3.0, "And": -3.0, " Und": -3.0, " albeit": -5.0,
               " moreover": -4.0, " although": -2.0}
PUNCT = {",", ";", ":", ".", "\n", "—", "–", " —", " –", " -", "-"}


def _recent_text(prefix, max_chars):
    """The text just before the current token, within the same document."""
    text = ""
    doc = prefix.document_ids[-1]
    for tok, d in zip(reversed(prefix.token_strings[:-1]), reversed(prefix.document_ids[:-1])):
        if d != doc or len(text) > max_chars:
            break
        text = tok + text
    return text


def _tail_word(text):
    word = ""
    for ch in reversed(text):
        if not ch.isalpha():
            break
        word = ch + word
    return word


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if len(tok) > 1 and tok[0] == "-" and tok[1].isupper():
        word = _tail_word(_recent_text(prefix, 30))
        if word[:1].isupper() and not word.isupper() and len(word) >= NAME_PART_MIN:
            return carry, 4.0
        return carry, 0.5
    if tok == ".":
        text = _recent_text(prefix, 120)
        if any(cue in text for cue in MATH_CUES) and "=" in text[-40:]:
            return carry, 4.0
        return carry, 0.0
    if tok in CONNECTIVES:
        if tok in (" And", "And", " Und") and len(prefix.token_strings) > 1:
            if prefix.token_strings[-2] not in PUNCT:
                return carry, 0.0
        return carry, CONNECTIVES[tok]
    return carry, 0.0

"""Layer 15 MLP down-projection, component 4852.

What it responds to: words of partial or just-begun progress and approach
("partially", "partly", "partial", "half", "start", "begin", "progress", "toward",
"close", "near", "attempt", "slowly") and words that name a part or quantity of a whole
("part", "portion", "piece", "some", "most", "many", "%").

The activation goes negative on those words. It is most negative on the word that
follows them in a construction of partial progress or approach: the "of" after a
part-word ("snippet of", "part of", "portion of", "some of"), and "to", "the", "in", "a"
after a partial-progress or approach word ("starting to", "closer to", "close to",
"attempt to", "toward the", "half the"). Other positions sit near zero.

The program states these values from the words alone, with a least-squares scale fitted
on training text. It explains only a few percent of the variance (about 0.04): the
component depends on context beyond these words.
"""

PARTIAL = {
    " partially", " partly", " partial", " somewhat", " slightly", " gradually",
    " slowly", " begun", " begin", " begins", " began", " beginning", " started",
    " start", " starting", " starts", " progress", " toward", " towards",
    " approaching", " closer", " close", " near", " attempt", " attempts", " attempted",
    " attempting", " half", " hint", " snippet", " glimpse", " fragment", " preliminary",
    " ongoing", " pending", " semi", " early",
}
APPROACH = {
    " contribute", " contributes", " contributed", " contributing", " contribution",
    " try", " trying", " tried", " seek", " seeking", " help", " about", " closest",
    " approach", " approaches", " add", " adds", " effort", " efforts",
}
PARTITIVE = {
    " part", " parts", " portion", " portions", " piece", " pieces", " half", " some",
    " bit", " fraction", " fragment", " segment", " slice", " snippet", " hint",
    " glimpse", " stage", " stages", " phase", " step", " few", " little", " quarter",
    " subset", " majority", " most", " many", " any", " one", "%",
}
FOLLOW = {" of", " to", " the", " in", " a", " for", " on"}


READS = ()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    same_doc = len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    if tok == " of" and prev in PARTITIVE:
        value = -3.0
    elif tok in FOLLOW and prev in PARTIAL:
        value = -2.0
    elif tok in FOLLOW and prev in APPROACH:
        value = -1.0
    elif tok in PARTIAL:
        value = -1.8
    elif tok in APPROACH:
        value = -0.3
    elif tok == " of":
        value = -0.5
    elif tok in PARTITIVE:
        value = -0.2
    else:
        value = 0.0
    return carry, float(value)

"""Layer 15, MLP hidden unit 4862 (this component reads almost only that unit).

Its activation is a signed value that token identity does not explain: a lookup on the
current token, or on the token pair, explains nothing held out, and a small network over the
last 8 tokens explains only about 3.5% of the variance. This program keeps the one weak
trend found in the data:

* the word "to" that follows an effort/attempt/time word ("trying to", "started to",
  "take time to", "need to", "get used to") is the most positive case;
* a verb right after "to", or a verb with an effort word just before it, is mildly positive;
* everything else is near 0.

Weights are least-squares fits on training rows, in activation units. It explains well under
1% of the variance on held-out data; it is a readable sketch, not a full account.
"""
import wordnet

READS = ()

# Words that signal an attempt, a start, a need, or time spent on something.
EFFORT = {
    "try", "trying", "tried", "tries", "start", "started", "starting", "begin", "began",
    "begins", "need", "needs", "needed", "time", "wait", "waiting", "take", "takes",
    "effort", "efforts", "attempt", "attempting", "get", "getting", "process", "work", "working",
}
W_TO_AFTER_EFFORT = 0.85  # "to" with an effort word within the last 4 tokens
W_TO_OTHER = 0.10  # any other "to"
W_VERB_AFTER_TO = 0.26  # a verb directly after "to"
W_VERB_AFTER_EFFORT = 0.24  # a verb with an effort word within the last 4 tokens


def _word(s):
    return s.strip().lower()


def _is_verb(w):
    return w.isalpha() and "verb" in wordnet.parts_of_speech(w)


def step(carry, prefix, upstream):
    strs = prefix.token_strings
    docs = prefix.document_ids
    cur = _word(strs[-1])
    # Look back at most 4 tokens, and not across a document boundary.
    back = []
    for i in range(len(strs) - 2, max(-1, len(strs) - 6), -1):
        if docs[i] != docs[-1]:
            break
        back.append(_word(strs[i]))
    prev = back[0] if back else ""
    effort = any(w in EFFORT for w in back)
    if cur == "to":
        value = W_TO_AFTER_EFFORT if effort else W_TO_OTHER
    elif prev == "to" and _is_verb(cur):
        value = W_VERB_AFTER_TO
    elif effort and _is_verb(cur):
        value = W_VERB_AFTER_EFFORT
    else:
        value = 0.0
    return carry, value
